do $$ declare r record; d text; pos integer; guard text:=E'begin\n if auth.uid() is null then raise exception ''Authentication required''; end if;'; begin for r in select p.oid,pg_get_functiondef(p.oid) def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and (p.proname like 'fleet_%' or p.proname like 'get_fleet_%') and pg_get_functiondef(p.oid) not ilike '%auth.uid()%' and p.proname not in ('fleet_actor_is_manager','fleet_metric_controller_authorized','fleet_observe_access') loop pos:=strpos(lower(r.def),'begin'); if pos>0 then d:=left(r.def,pos-1)||guard||substr(r.def,pos+5); execute d; end if; end loop; end $$;
